content = '''#!/usr/bin/env python3
import json, os, sys, argparse

def get_agent_dir():
    return os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'agents')

def search_agents(query):
    agents_dir = get_agent_dir()
    results = []
    if not os.path.exists(agents_dir):
        print(f'Error: Agents directory not found', file=sys.stderr)
        sys.exit(1)
    query_lower = query.lower()
    for fn in os.listdir(agents_dir):
        if fn.endswith('.json'):
            with open(os.path.join(agents_dir, fn)) as f:
                agent = json.load(f)
            matches = []
            if query_lower in agent['name'].lower():
                matches.append('name')
            if query_lower in agent['description'].lower():
                matches.append('description')
            if any(query_lower in t.lower() for t in agent.get('tags', [])):
                matches.append('tags')
            if matches:
                results.append({'name': agent['name'], 'description': agent['description'],
                    'tags': agent.get('tags', []), 'match_type': ', '.join(matches)})
    return results

def main():
    parser = argparse.ArgumentParser(description='Search agents')
    parser.add_argument('query', nargs='?', default='')
    parser.add_argument('--json', '-j', action='store_true')
    args = parser.parse_args()

    if not args.query:
        print('Usage: search.py <query> [--json]')
        print('Example: search.py security --json')
        sys.exit(1)

    results = search_agents(args.query)
    if args.json:
        print(json.dumps(results, indent=2))
    else:
        if not results:
            print(f\"No agents matching '{args.query}'\")
            print(\"Use 'get.py --list' to see all agents.\")
        else:
            print(f\"Found {len(results)} agent(s) matching '{args.query}':\")
            for a in results:
                print(f\"  {a['name']}\")
                print(f\"    {a['description']}\")
                print(f\"    Tags: {', '.join(a['tags'])}\")
                print(f\"    Matched: {a['match_type']}\")
                print()

if __name__ == '__main__':
    main()
'''
